      if (hole) { ctx.globalCompositeOperation = 'destination-out'; rr(r.x, r.y, r.w, r.h, r.w * 0.045); ctx.fillStyle = '#000'; ctx.fill(); ctx.globalCompositeOperation = 'source-over'; }
