    card.animate([{ opacity: 0, transform: 'scale(.85)' }, { opacity: 1, transform: 'scale(1)' }], { duration: 450, fill: 'forwards', easing: 'ease-out' });
    sfx.powerup(2.5); sfx.rumble();
