        enter(st, 'a', st.P.a.lead); enter(st, 'b', st.P.b.lead);
        const na = !!tp(st.P.a.team[st.P.a.lead], 'first') && !blocked(st, 'a'), nb = !!tp(st.P.b.team[st.P.b.lead], 'first') && !blocked(st, 'b');
