      const wait = h(`<div class="bb-zoom du-wait"><div><h3>Invitation envoyée à ${esc(p.pseudo)}</h3><p class="bb-muted">En attente de sa réponse…</p><button class="bb-btn ghost">Annuler</button></div></div>`);
